HWND OpenCredentialWindow(HWND owner,const std::filesystem::path& profile,bool turkish,std::function<CefRefPtr<CefBrowser>()> active,std::function<bool(CefRefPtr<CefBrowser>)> is_private){WNDCLASSW cls={};cls.hInstance=GetModuleHandleW(nullptr);cls.lpfnWndProc=Proc;cls.lpszClassName=ClassName;cls.hCursor=LoadCursor(nullptr,IDC_ARROW);cls.hbrBackground=reinterpret_cast<HBRUSH>(COLOR_WINDOW+1);RegisterClassW(&cls);auto state=std::make_shared<State>();state->tr=turkish;state->vault=std::make_shared<PasswordVault>(profile);state->active=std::move(active);state->is_private=std::move(is_private);auto holder=new std::shared_ptr<State>(state);auto hwnd=CreateWindowExW(WS_EX_DLGMODALFRAME,ClassName,turkish?L"Turan Parola Kasası":L"Turan Password Vault",WS_OVERLAPPED|WS_CAPTION|WS_SYSMENU|WS_VISIBLE, CW_USEDEFAULT,CW_USEDEFAULT,818,660,owner,nullptr,GetModuleHandleW(nullptr),holder);if(!hwnd&&!state->attached)delete holder;return hwnd;}
